//! 🧪️ Original encoder quote and cancellation replies survive real callback unwind.
use super::*;
use semio_framework_value_control_contract::{NativeAllocationAuthority,NativeAllocationAuthorityPort,NativeAllocationEvent,NativeAllocationReply,NativeAllocationReplyComplete,OriginalSourceTurnIdentity};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Producer{quotes:Arc<AtomicUsize>,cancels:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl NativeAllocationAuthorityPort for Producer{
 type Context<'turn,'source>=() where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity> where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{match event{NativeAllocationEvent::Quote(_)=>{self.quotes.fetch_add(1,Ordering::Relaxed);},NativeAllocationEvent::Cancel(_)=>{self.cancels.fetch_add(1,Ordering::Relaxed);},_=>panic!("unperformed original allocation cannot post")}let _reply=reply.complete(Ok(()));panic!("original allocation producer interrupted after reply")}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{self.recoveries.fetch_add(1,Ordering::Relaxed);Ok(reply.pending())}
}
#[test]
fn original_encoder_quote_and_cancel_preserve_recorded_reply_without_replay(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🛂️allocation/📊️progress/🧪️tests/reply.json")).unwrap();let quotes=Arc::new(AtomicUsize::new(0));let cancels=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut authority=NativeAllocationAuthority::new(Producer{quotes:quotes.clone(),cancels:cancels.clone(),recoveries:recoveries.clone()});let request=NativeAllocationRequest{bytes:7,owned_bytes:0,next_owned_bytes:7,maximum_bytes:7};let mut ledger=semio_framework_value_receiving::NativeAllocationLedger::new(0);let mut state=NativeEncodeAllocationProgress::new(request,None,Some(authority.identity()),true).unwrap();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_send_loan(&mut (),|loan|{let mut scoped=Some(loan as &mut dyn NativeSendAllocationLoan);advance_encode_quotes(&mut NativeEncodeAllocationBinding::Local,&mut scoped,&mut state).unwrap()}).unwrap()));assert!(interrupted.is_err());assert_eq!(state.scoped_phase(),NativeEncodeAllocationPhase::QuoteStarted);
 authority.with_send_loan(&mut (),|loan|{let mut scoped=Some(loan as &mut dyn NativeSendAllocationLoan);assert!(advance_encode_quotes(&mut NativeEncodeAllocationBinding::Local,&mut scoped,&mut state).unwrap())}).unwrap();
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_send_loan(&mut (),|loan|{let mut scoped=Some(loan as &mut dyn NativeSendAllocationLoan);settle_encode_allocation(&mut NativeEncodeAllocationBinding::Local,&mut scoped,&mut ledger,&mut state,None).unwrap()}).unwrap()));assert!(interrupted.is_err());assert_eq!(state.scoped_phase(),NativeEncodeAllocationPhase::SettlementStarted);assert_eq!(ledger.owned_bytes(),law["admittedBytes"].as_u64().unwrap()as usize);
 authority.with_send_loan(&mut (),|loan|{let mut scoped=Some(loan as &mut dyn NativeSendAllocationLoan);assert!(settle_encode_allocation(&mut NativeEncodeAllocationBinding::Local,&mut scoped,&mut ledger,&mut state,None).unwrap())}).unwrap();let outcome=state.into_outcome().ok().expect("original allocation settled");assert!(!outcome.admitted);assert_eq!(outcome.actual,None);assert_eq!(quotes.load(Ordering::Relaxed),law["quotes"].as_u64().unwrap()as usize);assert_eq!(cancels.load(Ordering::Relaxed),law["cancels"].as_u64().unwrap()as usize);assert_eq!(recoveries.load(Ordering::Relaxed),law["producerRecoveries"].as_u64().unwrap()as usize);assert!(authority.into_port().is_ok())
}
